// Determine trigger source and extract expense data
const webhookData = $input.first().json.body || {};
const emailData = $input.first().json;

// Check if coming from webhook or email
const isEmail = emailData.textHtml !== undefined || emailData.textPlain !== undefined;

let expenseData = {};

if (isEmail) {
  // Parse email content
  const emailText = emailData.textHtml || emailData.textPlain || '';
  const emailSubject = emailData.subject || '';
  const fromAddress = emailData.from?.value?.[0]?.address || '';

  // Look for attachments
  const attachments = emailData.attachments || [];
  const receiptAttachment = attachments.find(a => 
    a.contentType?.includes('pdf') || 
    a.contentType?.includes('image')
  );

  // Try to extract amount from subject or body
  const amountMatch = emailSubject.match(/R[\s]*([\d,]+\.?\d*)/) || 
                      emailText.match(/R[\s]*([\d,]+\.?\d*)/);
  const amount = amountMatch ? parseFloat(amountMatch[1].replace(/,/g, '')) : null;

  // Extract date patterns
  const dateMatch = emailText.match(/(\d{1,2}[/\-]\d{1,2}[/\-]\d{2,4})/);

  expenseData = {
    source: 'email',
    description: emailSubject,
    vendor_name: emailData.from?.value?.[0]?.name || fromAddress,
    amount: amount,
    date: dateMatch ? dateMatch[1] : new Date().toISOString().split('T')[0],
    ocr_text: emailText.substring(0, 5000),
    property_address: null,
    receipt_url: receiptAttachment?.attachmentId || null,
    email_from: fromAddress,
    email_subject: emailSubject,
    has_attachment: !!receiptAttachment
  };
} else {
  // Webhook data
  expenseData = {
    source: 'webhook',
    description: webhookData.description || '',
    vendor_name: webhookData.vendor_name || '',
    amount: webhookData.amount ? parseFloat(webhookData.amount) : null,
    date: webhookData.date || new Date().toISOString().split('T')[0],
    ocr_text: webhookData.ocr_text || webhookData.notes || '',
    property_address: webhookData.property_address || null,
    receipt_url: webhookData.receipt_url || null,
    submitted_by: webhookData.submitted_by || null
  };
}

// Validate required data
if (!expenseData.description && !expenseData.ocr_text) {
  return [{
    json: {
      error: true,
      message: 'No expense description or receipt text provided',
      source: expenseData.source
    }
  }];
}

return [{
  json: expenseData
}];

// Parse Groq AI categorization response
try {
  const aiResponse = $input.first().json;
  const promptData = $('Build Groq Prompt').item.json;

  const choice = aiResponse.choices && aiResponse.choices[0];
  if (!choice) {
    throw new Error('No choices in AI response');
  }

  const content = choice.message?.content || choice.text;
  let categorization;

  try {
    categorization = JSON.parse(content);
  } catch (parseError) {
    // Try to extract JSON from markdown code blocks
    const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
    if (jsonMatch) {
      categorization = JSON.parse(jsonMatch[1].trim());
    } else {
      throw new Error('Could not parse AI response as JSON');
    }
  }

  // Validate and normalize the categorization
  const normalizedCategory = categorization.expense_category || 'other';
  const validCategories = [
    'maintenance_repairs', 'utilities_electricity', 'utilities_water', 
    'rates_taxes', 'marketing_advertising', 'insurance', 'legal_professional',
    'cleaning_gardening', 'security', 'commission', 'office_expenses', 'other'
  ];

  const finalCategory = validCategories.includes(normalizedCategory) 
    ? normalizedCategory 
    : 'other';

  // Calculate VAT if not provided
  let vatAmount = categorization.vat_amount || 0;
  let vatInclusive = categorization.vat_inclusive !== false;

  // If VAT is 0 but amount is significant, calculate 15% VAT
  if (vatAmount === 0 && promptData.amount_cents > 0) {
    // Check if likely VAT inclusive based on vendor type
    const vendorType = categorization.vendor_type || '';
    const vatApplicableTypes = ['contractor', 'service_provider', 'retail'];

    if (vatApplicableTypes.includes(vendorType)) {
      const amount = promptData.amount_cents;
      // Assume VAT inclusive, extract VAT
      vatAmount = Math.round(amount * 15 / 115);
      vatInclusive = true;
    }
  }

  return [{
    json: {
      success: true,
      source: promptData.source,
      original_data: {
        description: promptData.description,
        vendor_name: promptData.vendor_name,
        amount_cents: promptData.amount_cents,
        date: promptData.date,
        receipt_url: promptData.receipt_url,
        submitted_by: promptData.submitted_by
      },
      categorization: {
        expense_category: finalCategory,
        category_confidence: categorization.category_confidence || 0.5,
        vendor_name: categorization.vendor_name || promptData.vendor_name,
        vendor_type: categorization.vendor_type || 'other',
        amount: categorization.amount || promptData.amount_cents / 100,
        vat_amount: vatAmount,
        vat_inclusive: vatInclusive,
        property_allocation: categorization.property_allocation || {
          suggested_property_id: null,
          confidence: 0,
          reasoning: 'No property match found'
        },
        is_duplicate: categorization.is_duplicate || false,
        duplicate_of: categorization.duplicate_of || null,
        flag_status: categorization.flag_status || 'normal',
        flags: categorization.flags || [],
        cost_center: categorization.cost_center || 'property_management',
        accounting_code: categorization.accounting_code || '',
        extracted_data: categorization.extracted_data || {},
        summary: categorization.summary || promptData.description
      },
      ai_model: aiResponse.model,
      tokens_used: aiResponse.usage?.total_tokens || 0
    }
  }];
} catch (error) {
  return [{
    json: {
      success: false,
      error: error.message,
      raw_response: $input.first().json
    }
  }];
}

// Check duplicate query results and prepare final data
const parsedData = $input.all()[0].json;
const duplicateCheck = $input.all()[1]?.json?.data || [];

if (!parsedData.success) {
  return [{
    json: {
      error: true,
      message: parsedData.error,
      stage: 'ai_parsing'
    }
  }];
}

const categorization = parsedData.categorization;

// Check if duplicates found
const isDuplicate = duplicateCheck.length > 0 || categorization.is_duplicate;
const duplicateOf = duplicateCheck.length > 0 ? duplicateCheck[0].id : categorization.duplicate_of;

// Update flags based on duplicate check
const flags = [...(categorization.flags || [])];
if (isDuplicate && !flags.includes('possible duplicate')) {
  flags.push('possible duplicate');
}

// Determine final flag status
let flagStatus = categorization.flag_status;
if (isDuplicate) {
  flagStatus = 'review_required';
} else if (parsedData.original_data.amount_cents > 1000000) { // > R10,000
  flagStatus = 'high_value';
  if (!flags.includes('high value expense')) {
    flags.push('high value expense');
  }
}

return [{
  json: {
    ...parsedData,
    categorization: {
      ...categorization,
      is_duplicate: isDuplicate,
      duplicate_of: duplicateOf,
      flag_status: flagStatus,
      flags: flags
    },
    duplicate_check: {
      checked: true,
      matches_found: duplicateCheck.length,
      matches: duplicateCheck.map(d => ({ id: d.id, created_at: d.created_at }))
    }
  }
}];

// Prepare notification for finance team
const data = $input.first().json;
const category = data.categorization;

const amount = (data.original_data.amount_cents / 100).toFixed(2);
const flagEmoji = {
  'unusual': '⚠️',
  'high_value': '💰',
  'review_required': '🚩',
  'normal': '✅'
}[category.flag_status] || '⚠️';

return [{
  json: {
    notification_type: 'expense_flagged',
    flag_status: category.flag_status,
    flags: category.flags,
    expense: {
      category: category.expense_category,
      vendor: category.vendor_name,
      amount: `R${amount}`,
      summary: category.summary,
      property_id: category.property_allocation.suggested_property_id,
      is_duplicate: category.is_duplicate
    },
    message: `${flagEmoji} EXPENSE FLAGGED: ${category.flag_status.toUpperCase()}`,
    details: `Vendor: ${category.vendor_name}\nAmount: R${amount}\nCategory: ${category.expense_category}\nFlags: ${category.flags.join(', ')}`,
    review_url: `https://agentloop.co.za/admin/expenses/${data.saved_id || 'review'}`
  }
}];

// Handle errors from any previous node
const input = $input.first().json;

if (input.error) {
  return [{
    json: {
      status: 'error',
      error_type: input.error === true ? 'validation_error' : 'processing_error',
      message: input.message || input.error || 'Unknown error occurred',
      stage: input.stage || 'unknown'
    }
  }];
}

// Pass through successful data
return $input.all();

// Prepare final response
const data = $input.first().json;

if (data.error) {
  return [{
    json: {
      status: 'error',
      message: data.message || data.error,
      categorization: null
    }
  }];
}

const cat = data.categorization;
const amount = (data.original_data.amount_cents / 100).toFixed(2);

return [{
  json: {
    status: 'success',
    message: 'Expense categorized successfully',
    expense: {
      id: data.saved_id,
      category: cat.expense_category,
      category_display: cat.expense_category.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
      vendor: cat.vendor_name,
      amount: `R${amount}`,
      vat_amount: `R${(cat.vat_amount / 100).toFixed(2)}`,
      property_allocation: cat.property_allocation,
      flag_status: cat.flag_status,
      flags: cat.flags,
      is_duplicate: cat.is_duplicate,
      summary: cat.summary,
      cost_center: cat.cost_center,
      accounting_code: cat.accounting_code
    },
    ai_analysis: {
      confidence: cat.category_confidence,
      model: data.ai_model,
      tokens_used: data.tokens_used
    },
    next_steps: cat.flag_status === 'normal' 
      ? ['Expense ready for accounting export']
      : ['Finance team notified for review', 'Awaiting approval before export']
  }
}];
